INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10081003, 4100810, "物理防御力（ダウン不可）アップ", "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", "boss_def_lower_limit");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10081004, 4100810, "魔法防御力（ダウン不可）アップ", "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", "boss_magic_def_lower_limit");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10081005, 4100810, "ＴＰダウンカット", "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", "boss_tp_down_cut");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10081006, 4100810, "ＴＰ上昇ダウン", "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 3);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (10081007, 4100810, "ＨＰ吸収ダウン", "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 9);
